// --- Setup: load settings, create peer, generate offer, attempt QR ---
useEffect(() => {
  let cancelled = false
  void (async () => {
    const [s, profile] = await Promise.all([
      loadSettings(),
      loadActiveProfile(),
    ])
    if (cancelled) return
    const ip = s.laptopLanIp?.trim() ?? ''
    setLanIp(ip || null)
    setActiveProfile(profile)

    // Reuse an already-connected peer so the athlete can reopen PairScreen
    // (e.g. to recalibrate) without tearing down their pairing. Per
    // decision-memo §2b.4, the peer's lifetime is owned by the phone-peer
    // slice, not by PairScreen's mount.
    const existing = getActivePhonePeer()
    if (existing && existing.state === 'connected') {
      peerRef.current = existing
      setPeerState('connected')
      setQrState('connected')
      setStartedAt(Date.now())
      return
    }

    const peer = createPeer()
    peerRef.current = peer
    attachPhonePeer(peer)
    peer.onStateChange((next) => {
      if (cancelled) return
      setPeerState(next)
      if (next === 'connected') {
        setQrState('connected')
        // Reset the RTT baseline so "Last commit received at +Xms" is the
        // pure phone→laptop send time the M5 manual gate budgets at <200ms,
        // not the offer-creation + scan + handshake elapsed.
        setStartedAt(Date.now())
        // Hand the phone the per-athlete threshold so the motion runner
        // (Phase 2b.3) arms with the right value the moment the
        // DataChannel opens. No threshold yet → use the default.
        try {
          peer.send({
            type: 'config',
            thresholdG: getActiveThresholdG(profile),
            debounceMs: DEFAULT_DEBOUNCE_MS,
            mode: 'armed',
          })
        } catch {
          /* peer not actually open yet — phone defaults to armed anyway */
        }
      }
    })
    peer.onMessage((m: PhoneMessage) => {
      if (m.type === 'commit') {
        setLastCommit({ receivedAt: Date.now(), sentAt: m.t })
      }
    })

    setStartedAt(Date.now())
    try {
      const sdp = await peer.createOffer()
      if (cancelled) return
      setOfferSdp(sdp)
      const enc = await tryEncodeOffer(sdp)
      if (!enc.ok) {
        setMode('manual')
        setAutoFallbackReason(
          `Pairing payload (${enc.byteLength} bytes) is too large for one QR — using manual paste.`,
        )
        setQrState('showing-offer')
        return
      }
      if (!ip) {
        setMode('manual')
        setAutoFallbackReason(
          'Set your laptop’s LAN IP in Settings to enable QR pairing. Using manual paste.',
        )
        setQrState('showing-offer')
        return
      }
      const url = buildPhoneUrl(
        {
          protocol: window.location.protocol,
          lanIp: ip,
          port: window.location.port,
        },
        enc.payload,
      )
      setPhoneUrl(url)
      setQrState('showing-offer')
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
      setQrState('error')
    }
  })()
  return () => {
    cancelled = true
    stopScanning()
    // Peer lifetime is owned by the phone-peer slice, not PairScreen —
    // closing here would tear down a pairing the athlete needs to drill
    // with. Explicit disconnect is exposed via `handleDisconnect`.
  }
}, [])

function handleDisconnect(): void {
  detachPhonePeer()
  peerRef.current = null
  setPeerState('idle')
  setQrState('preparing-offer')
  setOfferSdp('')
  setAnswerSdp('')
  setPhoneUrl(null)
  setLastCommit(null)
  setStartedAt(null)
}

